// Local-only screenshot harness: mounts the real page against a scripted mock
// host so CSS changes can be looked at in a browser. Not part of the bundle.
import { createRoot } from 'react-dom/client';
import { App } from './App';
import { applyAppearance } from './tokens';
import { Envelope, PROTOCOL_NAME, PROTOCOL_VERSION, StatePayload, WorkspaceContext } from './bridge/protocol';
import './styles.css';

const context: WorkspaceContext = {
  sessionId: '1', revision: 4, projectName: 'Two Cubes', projectDirty: true,
  printer: { preset: 'Bambu Lab X1C 0.4', filament: 'Generic PLA' },
  plates: [{ id: '11', name: 'Plate 1', active: true, sliced: true,
    objects: [{ id: '21', name: 'cube-a', instances: 2, selected: true },
              { id: '22', name: 'cube-b', instances: 1, selected: false }] }],
  selection: { status: 'objects', objectIds: ['21'] },
