  activeConversationId: 'conv-1',
  conversation: [
    { id: 'm-1', role: 'user', state: 'complete', attempt: 1,
      text: 'Duplicate cube-a and slice plate 1.' },
    { id: 'm-2', role: 'assistant', state: 'complete', attempt: 1, inReplyTo: 'm-1',
