    expectedOutputHash: '9f8e7d6c5b4a3928', observedOutputHash: '9f8e7d6c5b4a3928', verified: true, modified: false }],
  physicalPrints: [{ id: 'pp-1', seq: 1, startedAt: '2026-09-07T10:10:00Z', endedAt: '2026-09-07T11:40:00Z',
    outcome: 'completed', failure: '', buildId: 'b-1', projectId: 'p-1', revisionId: 'r-1',
    conversationId: 'conv-1', afterMessageId: 'm-2', plateIndex: 0, plateName: 'Plate 1',
    printer: 'Bambu Lab X1C 0.4', material: 'Generic PLA',
    manufacturingInputHash: 'a1b2c3d4e5f6a7b8', outputHash: '9f8e7d6c5b4a3928', gcodeHash: '3c2b1a0f9e8d7c6b',
    statistics: stats, timelineRemoved: true }],
  draft: 'Now raise the infill to 30%',
  attachments: [
    { id: 'a-1', name: 'bracket-notes.txt', kind: 'text', mime: 'text/plain', sizeBytes: 1420,
      source: 'file', state: 'staged', previewText: 'Wall thickness must clear the M3 insert.' },
    { id: 'a-2', name: 'reference.png', kind: 'image', mime: 'image/png', sizeBytes: 20480,
      source: 'file', state: 'staged',
      previewDataUrl: 'data:image/svg+xml;base64,' + btoa('<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48"><rect width="48" height="48" fill="#4a7"/></svg>') },
