python3 - <<'PY'
p='src/dev-main.tsx'
s=open(p).read()
old = """const transport = {
  post: (json: string) => {
    const env = JSON.parse(json) as Envelope;
    if (env.type !== 'hello') return;
    const send = (type: string, payload: unknown) =>
      window.__jusprinBridge!.deliver({ protocol: PROTOCOL_NAME, version: PROTOCOL_VERSION, id: `h-${type}`, type, payload });
    queueMicrotask(() => {
      send('hello_ack', { version: PROTOCOL_VERSION, agent: state.agent, appearance: state.appearance });
      send('state', state);
    });
  },
};"""
new = """const catalog = {
  helperPresent: true,
  tools: [
    { id: 'claude-code', name: 'Claude Code', subtitle: 'Anthropic CLI', detected: true, cli: true,
      text: 'Detected', configPath: '/Users/you/.claude/settings.json' },
    { id: 'cursor', name: 'Cursor', subtitle: 'Editor', detected: true, cli: false,
      text: 'Detected', configPath: '/Users/you/.cursor/mcp.json' },
    { id: 'zed', name: 'Zed', subtitle: 'Editor', detected: false, cli: false, text: 'Not found' },
  ],
};

const preview = {
  toolId: 'claude-code',
  path: '/Users/you/.claude/settings.json',
  root: 'mcpServers',
  previous: '{\\n  "mcpServers": {}\\n}',
  next: '{\\n  "mcpServers": {\\n    "jusprin": {\\n      "command": "/Applications/JusPrin.app/Contents/MacOS/jusprin-mcp"\\n    }\\n  }\\n}',
};

const send = (type: string, payload: unknown) =>
  window.__jusprinBridge!.deliver({ protocol: PROTOCOL_NAME, version: PROTOCOL_VERSION, id: `h-${type}-${Math.random()}`, type, payload });

const transport = {
  post: (json: string) => {
    const env = JSON.parse(json) as Envelope;
    queueMicrotask(() => {
      if (env.type === 'hello') {
        send('hello_ack', { version: PROTOCOL_VERSION, agent: state.agent, appearance: state.appearance });
        send('state', state);
      }
      if (env.type === 'mcp_catalog') send('mcp_catalog', catalog);
      if (env.type === 'mcp_preview') send('mcp_preview', preview);
      if (env.type === 'mcp_connect') send('mcp_status', { phase: 'writing', toolId: 'claude-code' });
    });
  },
};

// Drive the setup screens from the URL: ?screen=tool|chooser|apikey, ?step=review|error
(window as unknown as { __harness: unknown }).__harness = { send, catalog, preview };"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
print('patched')
PY

