  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font: inherit;
  font-size: 13px;
  line-height: 18px;
  padding: 6px 12px;
  border-radius: 4px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-primary);
  cursor: pointer;
}

.attach-button {
  flex: 0 0 auto;
  width: 36px;
  height: 36px;
  font-size: 20px;
  line-height: 1;
  border-radius: 4px;
  border: 1px solid var(--border-subtle);
  background: var(--surface-raised);
  color: var(--text-primary);
  cursor: pointer;
}

.attach-button:disabled {
  opacity: 0.5;
  cursor: default;
}

.attachment-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  max-width: 240px;
  padding: 4px 6px;
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  background: var(--surface-raised);
}

.attachment-chip.errored {
  border-color: var(--status-danger);
}

.attachment-thumb {
  width: 28px;
  height: 28px;
  object-fit: cover;
  border-radius: 4px;
  flex: 0 0 auto;
}

.attachment-kind {
  font-size: 10px;
.composer textarea {
  flex: 1;
  resize: none;
  font: inherit;
  padding: 8px;
  border-radius: 4px;
  border: 1px solid var(--border-subtle);
  background: var(--surface-canvas);
  color: var(--text-primary);
  min-height: 36px;

