import re
lines=open('src/styles.css').read().split('\n')
sel=None; brace=0
for i,l in enumerate(lines,1):
    st=l.strip()
    if '{' in st and not st.startswith('@'):
        sel=st.split('{')[0].strip() or sel
        # multi-line selector: walk back
        if not sel:
            sel=lines[i-2].strip()
    if re.search(r'font(-size)?: *(11|13|16|20)px|font: *(11|13|16|20)px', st):
        # find governing selector by walking backwards for the nearest '{'
        j=i-1; depth=0; s=None
        while j>0:
            t=lines[j-1]
            if '}' in t and j!=i: depth+=t.count('}')
            if '{' in t:
                if depth==0: s=t.split('{')[0].strip() or (lines[j-2].strip() if j>1 else '')
                else: depth-=t.count('{')
                if s: break
            j-=1
        print(f"{i:5}  {st[:95]:<97} <- {s}")
