python3 - <<'PY'
import re
p='src/styles.css'
s=open(p).read()

# Body and control: 14/20. Every 13px in the panel is running text, control
# text, or preformatted content the reader is meant to read.
pairs13 = [
 ("font-size: 13px; }", "font-size: 14px; line-height: 20px; }"),
 ("font-size: 13px; line-height: 18px;", "font-size: 14px; line-height: 20px;"),
 ("  font-size: 13px;\n  line-height: 18px;", "  font-size: 14px;\n  line-height: 20px;"),
]
for a,b in pairs13:
    s = s.replace(a,b)

# Dense metadata: 10/14. Timestamps, subtitles, warnings, footnotes.
pairs11 = [
 ("font-size: 11px; color:", "font-size: 10px; line-height: 14px; color:"),
 ("font-size: 11px; line-height: 14px;", "font-size: 10px; line-height: 14px;"),
 ("  font-size: 11px;\n  line-height: 16px;", "  font-size: 10px;\n  line-height: 14px;"),
]
for a,b in pairs11:
    s = s.replace(a,b)

# Section: 18/24. Both remaining 16px headings.
s = s.replace(".chat-dialog h2 { margin: 0 0 12px; font-size: 16px; line-height: 22px; }",
              ".chat-dialog h2 { margin: 0 0 12px; font-size: 18px; line-height: 24px; }")
s = s.replace(""".markdown-content h2 {
  font-size: 16px;
  line-height: 20px;
}""", """.markdown-content h2 {
  font-size: 18px;
  line-height: 24px;
}""")
open(p,'w').write(s)
PY
